contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount param and send it to c.play{value: amount}().
    // The test checks that if the call succeeds (or reverts) and the amount == TICKET_AMOUNT,
    // then the balance of the bank (as observable via address(c).balance and c.pot())
    // does not indicate a decrease of the bank's balance compared to before the call.
    // Because bank is an externally owned address, we cannot read its balance directly from c,
    // but we can reason about address(c).balance and c.pot() to infer whether the bank was paid
    // (bank receiving FEE_AMOUNT moves Ether out of contract). The intended invariant: the bank's
    // absolute balance cannot decrease as a result of play() — i.e., play() never drains Ether from the bank.

    // To express this using only public observations: before the call, contract balance = pot_before.
    // After a successful payout where bank is paid FEE_AMOUNT, contract balance decreases by FEE_AMOUNT
    // and pot becomes 0, which is consistent with bank receiving FEE_AMOUNT. There is no observable
    // case where the bank loses Ether (which would correspond to an increase in contract balance without
    // corresponding pot increase). We assert that after a call with the exact ticket amount, the contract's
    // balance is never greater than its previous balance plus the ticket amount (i.e., the bank wasn't drained).

    // Note: We must not use msg.value of this test; we pass amount as parameter and ensure balance available.

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");

        uint bal_before = address(c).balance;
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint bal_after = address(c).balance;
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;

        // General rule: If caller paid exactly the ticket amount (amount == TICKET_AMOUNT), then
        // the contract's balance after the call cannot exceed bal_before + amount.
        // This forbids any behavior where the bank's external balance would be decreased (which
        // would require the contract to somehow receive extra Ether from the bank during play).
        // The assertion is stated only in terms of public observations: address(c).balance and input amount.
        assert(amount != 0 ? bal_after <= bal_before + amount : bal_after <= bal_before + amount);
    }
}

